use InnoCMS\Common\Models\Page;
use InnoCMS\Common\Models\Setting;
use InnoCMS\Common\Models\Tag;

return function (string $themeDir): void {
    $themeCode = basename($themeDir);
    $img       = static fn (string $rel): string => 'static/themes/'.$themeCode.'/images/'.$rel;

    precision_truncate();
    precision_seed_settings();
    precision_seed_catalogs();
    precision_seed_tags();
    precision_seed_articles($img);
    precision_seed_pages($img);
};

function precision_truncate(): void
{
    $driver = DB::getDriverName();
    $off    = $driver === 'sqlite' ? 'PRAGMA foreign_keys = OFF' : 'SET FOREIGN_KEY_CHECKS=0';
    $on     = $driver === 'sqlite' ? 'PRAGMA foreign_keys = ON' : 'SET FOREIGN_KEY_CHECKS=1';
    DB::statement($off);
    foreach ([ArticleTag::class, Article\Translation::class, Article::class, Catalog\Translation::class, Catalog::class, Page\Translation::class, Page::class, Tag\Translation::class, Tag::class] as $m) {
        $m::query()->truncate();
    }
    DB::statement($on);
}

