function precision_seed_tags(): void
{
    $tags = [
        [1, 'cnc-machining', 'CNC加工', 'CNC Machining'],
        [2, 'precision-parts', '精密零件', 'Precision Parts'],
        [3, 'oem-odm', 'OEM/ODM', 'OEM/ODM'],
        [4, 'iso-9001', 'ISO 9001', 'ISO 9001'],
        [5, 'aluminum', '铝合金', 'Aluminum'],
        [6, 'stainless-steel', '不锈钢', 'Stainless Steel'],
        [7, 'five-axis', '五轴加工', '5-Axis'],
        [8, 'rapid-prototyping', '快速打样', 'Rapid Prototyping'],
    ];
    foreach ($tags as [$id, $slug, $zh, $en]) {
        Tag::query()->create(['id' => $id, 'slug' => $slug, 'position' => $id, 'active' => 1]);
        Tag\Translation::query()->create(['tag_id' => $id, 'locale' => 'zh-cn', 'name' => $zh]);
        Tag\Translation::query()->create(['tag_id' => $id, 'locale' => 'en', 'name' => $en]);
    }
}

/**
 * @return array<int, array{0:int,1:int,2:string,3:string,4:int,5:array<int,int>,6:array,7:array}>
